-- 20261013000000_casino_games.sql
-- ZyroBet casino games (Slots, Crash, Plinko, Mines) played with virtual coins.
--
-- Outcomes are generated by the `casino-play` Edge Function from a hidden server seed
-- (provably fair: its SHA-256 hash is shown before the round, the seed after it).
-- Bets and payouts only move through apply_coin_transaction inside these
-- service-role-only functions; clients can read their own rounds and nothing else.

-- 1. Allow casino ledger reasons (only if the strict reason check exists)
do $$
begin
  if exists (
    select 1 from pg_constraint
    where conname = 'coin_ledger_reason_check'
      and conrelid = 'public.coin_ledger'::regclass
  ) then
    alter table public.coin_ledger drop constraint coin_ledger_reason_check;
    alter table public.coin_ledger add constraint coin_ledger_reason_check check (
      reason in (
        'signup_bonus', 'daily_reward', 'game_reward', 'purchase', 'spend', 'admin_adjust',
        'casino_bet', 'casino_win'
      )
    );
  end if;
end $$;

-- 2. Catalog rows
insert into public.games (id, slug, title, category, thumb_url, is_new, is_hot, sort_order, enabled)
values
  ('slots', 'lucky-reels', 'Lucky Reels', 'casino', '', true, true, 20, true),
  ('crash', 'crash', 'Crash', 'casino', '', true, true, 21, true),
  ('plinko', 'plinko', 'Plinko', 'casino', '', true, false, 22, true),
  ('mines', 'mines', 'Mines', 'casino', '', true, false, 23, true)
on conflict (id) do update set
  slug = excluded.slug,
  title = excluded.title,
  category = excluded.category,
  thumb_url = excluded.thumb_url,
  is_new = excluded.is_new,
  is_hot = excluded.is_hot,
  sort_order = excluded.sort_order,
  enabled = excluded.enabled;

-- 3. Bet limits per casino game
create table if not exists public.casino_config (
  game_id text primary key references public.games(id) on delete cascade,
  min_bet bigint not null check (min_bet > 0),
  max_bet bigint not null check (max_bet >= min_bet),
  max_payout bigint not null check (max_payout > 0),
  enabled bool not null default true
);

insert into public.casino_config (game_id, min_bet, max_bet, max_payout, enabled)
values
  ('slots', 10, 5000, 1000000, true),
  ('crash', 10, 5000, 1000000, true),
  ('plinko', 10, 5000, 1000000, true),
  ('mines', 10, 5000, 1000000, true)
on conflict (game_id) do update set
  min_bet = excluded.min_bet,
  max_bet = excluded.max_bet,
  max_payout = excluded.max_payout,
  enabled = excluded.enabled;

-- 4. Rounds (public part) and secrets (never readable by clients)
create table if not exists public.casino_rounds (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  game_id text not null references public.games(id),
  bet bigint not null check (bet > 0),
  status text not null check (status in ('active', 'settled')),
  params jsonb not null default '{}'::jsonb,
  state jsonb not null default '{}'::jsonb,
  multiplier numeric(12, 2),
  payout bigint not null default 0 check (payout >= 0),
  server_seed_hash text not null,
  client_seed text not null,
  -- Revealed only once the round is settled
  server_seed text,
  version int not null default 0,
  created_at timestamptz not null default now(),
  finished_at timestamptz
);

create index if not exists idx_casino_rounds_user_created
  on public.casino_rounds (user_id, created_at desc);

-- At most one unfinished round per user and game (Mines / Crash)
create unique index if not exists uniq_casino_rounds_active
  on public.casino_rounds (user_id, game_id)
  where status = 'active';

create table if not exists public.casino_round_secrets (
  round_id uuid primary key references public.casino_rounds(id) on delete cascade,
  server_seed text not null,
  secret jsonb not null default '{}'::jsonb
);

alter table public.casino_config enable row level security;
alter table public.casino_rounds enable row level security;
alter table public.casino_round_secrets enable row level security;

drop policy if exists "casino_config_select_all" on public.casino_config;
create policy "casino_config_select_all"
  on public.casino_config
  for select
  using (true);

drop policy if exists "casino_rounds_select_own" on public.casino_rounds;
create policy "casino_rounds_select_own"
  on public.casino_rounds
  for select
  to authenticated
  using (auth.uid() = user_id);

-- casino_round_secrets: no policies at all, so only service_role can touch it.

-- 5. JSON shape returned to the Edge Function
create or replace function public.casino_round_json(p_round public.casino_rounds)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select jsonb_build_object(
    'round', jsonb_build_object(
      'id', p_round.id,
      'gameId', p_round.game_id,
      'bet', p_round.bet,
      'status', p_round.status,
      'params', p_round.params,
      'state', p_round.state,
      'multiplier', p_round.multiplier,
      'payout', p_round.payout,
      'serverSeedHash', p_round.server_seed_hash,
      'clientSeed', p_round.client_seed,
      'serverSeed', p_round.server_seed,
      'version', p_round.version,
      'createdAt', p_round.created_at,
      'finishedAt', p_round.finished_at
    ),
    'balance', coalesce((select balance from public.wallets where user_id = p_round.user_id), 0)
  );
$$;

-- Read one round (with balance) for its owner.
create or replace function public.casino_get_round(p_user uuid, p_round uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_round public.casino_rounds%rowtype;
begin
  select * into v_round
  from public.casino_rounds
  where id = p_round and user_id = p_user;

  if not found then
    raise exception 'ROUND_NOT_FOUND';
  end if;

  return public.casino_round_json(v_round);
end;
$$;

-- 6. Settle a round: credit floor(bet * multiplier) (capped), reveal the server seed.
-- Idempotent: settling an already settled round returns it unchanged.
create or replace function public.casino_settle_round(
  p_user uuid,
  p_round uuid,
  p_multiplier numeric,
  p_state jsonb default null,
  p_expected_version int default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_round public.casino_rounds%rowtype;
  v_max_payout bigint;
  v_payout bigint;
begin
  perform pg_advisory_xact_lock(hashtext('casino:' || p_user::text));

  select * into v_round
  from public.casino_rounds
  where id = p_round
  for update;

  if not found then
    raise exception 'ROUND_NOT_FOUND';
  end if;

  if v_round.user_id <> p_user then
    raise exception 'ROUND_FORBIDDEN';
  end if;

  if v_round.status <> 'active' then
    return public.casino_round_json(v_round);
  end if;

  if p_expected_version is not null and v_round.version <> p_expected_version then
    raise exception 'ROUND_CONFLICT';
  end if;

  if p_multiplier is null or p_multiplier < 0 then
    raise exception 'INVALID_MULTIPLIER';
  end if;

  select max_payout into v_max_payout
  from public.casino_config
  where game_id = v_round.game_id;

  v_payout := least(floor(v_round.bet * p_multiplier)::bigint, coalesce(v_max_payout, 1000000));

  if v_payout > 0 then
    perform public.apply_coin_transaction(
      p_user,
      v_payout,
      'casino_win',
      v_round.id::text,
      'casino_win:' || v_round.id::text
    );
  end if;

  update public.casino_rounds r
  set status = 'settled',
      multiplier = p_multiplier,
      payout = v_payout,
      state = coalesce(p_state, r.state),
      server_seed = (select s.server_seed from public.casino_round_secrets s where s.round_id = r.id),
      version = r.version + 1,
      finished_at = now()
  where r.id = p_round
  returning * into v_round;

  return public.casino_round_json(v_round);
end;
$$;

-- 7. Open a round: validate limits, debit the bet, store the secret.
-- Instant games (Slots, Plinko) pass p_settle_multiplier to settle in the same transaction.
create or replace function public.casino_open_round(
  p_user uuid,
  p_game text,
  p_bet bigint,
  p_params jsonb,
  p_state jsonb,
  p_server_seed text,
  p_server_seed_hash text,
  p_client_seed text,
  p_secret jsonb,
  p_settle_multiplier numeric default null,
  p_settle_state jsonb default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_config public.casino_config%rowtype;
  v_round public.casino_rounds%rowtype;
begin
  perform pg_advisory_xact_lock(hashtext('casino:' || p_user::text));

  select c.* into v_config
  from public.casino_config c
  join public.games g on g.id = c.game_id
  where c.game_id = p_game and c.enabled and g.enabled;

  if not found then
    raise exception 'GAME_DISABLED';
  end if;

  if p_bet is null or p_bet < v_config.min_bet or p_bet > v_config.max_bet then
    raise exception 'INVALID_BET';
  end if;

  if exists (
    select 1 from public.casino_rounds
    where user_id = p_user and game_id = p_game and status = 'active'
  ) then
    raise exception 'ROUND_ACTIVE';
  end if;

  -- Checked here so the caller gets a clean INSUFFICIENT_COINS error
  if coalesce((select balance from public.wallets where user_id = p_user), 0) < p_bet then
    raise exception 'INSUFFICIENT_COINS';
  end if;

  insert into public.casino_rounds (
    user_id, game_id, bet, status, params, state, server_seed_hash, client_seed
  )
  values (
    p_user, p_game, p_bet, 'active', coalesce(p_params, '{}'::jsonb),
    coalesce(p_state, '{}'::jsonb), p_server_seed_hash, p_client_seed
  )
  returning * into v_round;

  insert into public.casino_round_secrets (round_id, server_seed, secret)
  values (v_round.id, p_server_seed, coalesce(p_secret, '{}'::jsonb));

  -- Raises INSUFFICIENT_COINS and rolls the whole round back if the wallet is short
  perform public.apply_coin_transaction(
    p_user,
    -p_bet,
    'casino_bet',
    v_round.id::text,
    'casino_bet:' || v_round.id::text
  );

  if p_settle_multiplier is not null then
    return public.casino_settle_round(p_user, v_round.id, p_settle_multiplier, p_settle_state, null);
  end if;

  return public.casino_round_json(v_round);
end;
$$;

-- 8. Update the public state of an active round (Mines reveals), with optimistic locking.
create or replace function public.casino_update_round_state(
  p_user uuid,
  p_round uuid,
  p_expected_version int,
  p_state jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_round public.casino_rounds%rowtype;
begin
  select * into v_round
  from public.casino_rounds
  where id = p_round
  for update;

  if not found then
    raise exception 'ROUND_NOT_FOUND';
  end if;

  if v_round.user_id <> p_user then
    raise exception 'ROUND_FORBIDDEN';
  end if;

  if v_round.status <> 'active' then
    raise exception 'ROUND_FINISHED';
  end if;

  if v_round.version <> p_expected_version then
    raise exception 'ROUND_CONFLICT';
  end if;

  update public.casino_rounds
  set state = p_state,
      version = version + 1
  where id = p_round
  returning * into v_round;

  return public.casino_round_json(v_round);
end;
$$;

revoke execute on function public.casino_round_json(public.casino_rounds) from public, anon, authenticated;
revoke execute on function public.casino_get_round(uuid, uuid) from public, anon, authenticated;
revoke execute on function public.casino_settle_round(uuid, uuid, numeric, jsonb, int) from public, anon, authenticated;
revoke execute on function public.casino_open_round(uuid, text, bigint, jsonb, jsonb, text, text, text, jsonb, numeric, jsonb) from public, anon, authenticated;
revoke execute on function public.casino_update_round_state(uuid, uuid, int, jsonb) from public, anon, authenticated;
grant execute on function public.casino_round_json(public.casino_rounds) to service_role;
grant execute on function public.casino_get_round(uuid, uuid) to service_role;
grant execute on function public.casino_settle_round(uuid, uuid, numeric, jsonb, int) to service_role;
grant execute on function public.casino_open_round(uuid, text, bigint, jsonb, jsonb, text, text, text, jsonb, numeric, jsonb) to service_role;
grant execute on function public.casino_update_round_state(uuid, uuid, int, jsonb) to service_role;
